        }

        public static PMAttackAck ParseFrom(byte[] data, int offset, int count)
        {
            PMAttackAck m = new PMAttackAck();
            MergeFrom(new PMNetReader(data, offset, count), m);
            return m;
        }

    }

    // AuthoritativePlayerState 的静态序列化器（无反射，可 AOT）。
    public static class PMAuthoritativePlayerStateSerializer
    {
        // 字段描述符表：供复制层与调试工具按字段号查元信息。
        public static readonly PMNetFieldDesc[] Fields = new PMNetFieldDesc[]
        {
            new PMNetFieldDesc(1, "battle_id", PMWireType.Varint, false),
            new PMNetFieldDesc(2, "pos_x", PMWireType.Fixed32, false),
            new PMNetFieldDesc(3, "pos_y", PMWireType.Fixed32, false),
            new PMNetFieldDesc(4, "pos_z", PMWireType.Fixed32, false),
            new PMNetFieldDesc(5, "hp", PMWireType.Varint, false),
            new PMNetFieldDesc(6, "is_dead", PMWireType.Varint, false),
            new PMNetFieldDesc(7, "state_mask", PMWireType.Varint, false),
            new PMNetFieldDesc(8, "mana", PMWireType.Varint, false),
            new PMNetFieldDesc(9, "super_energy", PMWireType.Varint, false),
        };

        // 序列化。字段按字段号升序写出，与 protoc 生成的 WriteTo 保持一致。
        public static void Write(PMNetWriter w, PMAuthoritativePlayerState m)
        {
            if (m == null)
            {
                return;
            }

            if (m.BattleId != 0)
            {
                w.WriteTag(1, PMWireType.Varint);
                w.WriteInt32(m.BattleId);
            }

            if (m.PosX != 0f)
            {
                w.WriteTag(2, PMWireType.Fixed32);
                w.WriteFloat(m.PosX);
            }

            if (m.PosY != 0f)
            {
                w.WriteTag(3, PMWireType.Fixed32);
                w.WriteFloat(m.PosY);
            }

            if (m.PosZ != 0f)
            {
                w.WriteTag(4, PMWireType.Fixed32);
                w.WriteFloat(m.PosZ);
            }

            if (m.Hp != 0)
            {
                w.WriteTag(5, PMWireType.Varint);
                w.WriteInt32(m.Hp);
            }

            if (m.IsDead)
            {
                w.WriteTag(6, PMWireType.Varint);
                w.WriteBool(m.IsDead);
            }

            if (m.StateMask != 0)
            {
                w.WriteTag(7, PMWireType.Varint);
                w.WriteUInt32(m.StateMask);
            }

            if (m.Mana != 0)
            {
                w.WriteTag(8, PMWireType.Varint);
                w.WriteInt32(m.Mana);
            }

            if (m.SuperEnergy != 0)
            {
                w.WriteTag(9, PMWireType.Varint);
                w.WriteInt32(m.SuperEnergy);
            }

        }

        // 反序列化（合并语义，与 protobuf MergeFrom 一致）。未知字段按 wire type 跳过。
        public static void MergeFrom(PMNetReader r, PMAuthoritativePlayerState m)
        {
            if (m == null)
            {
                return;
            }

            int fieldNumber;
            PMWireType wireType;
            while (r.ReadTag(out fieldNumber, out wireType))
            {
                switch (fieldNumber)
                {
                    case 1:
                    {
                        m.BattleId = r.ReadInt32();
                        break;
                    }
                    case 2:
                    {
                        m.PosX = r.ReadFloat();
                        break;
                    }
                    case 3:
                    {
                        m.PosY = r.ReadFloat();
                        break;
                    }
                    case 4:
                    {
                        m.PosZ = r.ReadFloat();
                        break;
                    }
                    case 5:
                    {
                        m.Hp = r.ReadInt32();
                        break;
                    }
                    case 6:
                    {
                        m.IsDead = r.ReadBool();
                        break;
                    }
                    case 7:
                    {
                        m.StateMask = r.ReadUInt32();
                        break;
                    }
                    case 8:
                    {
                        m.Mana = r.ReadInt32();
                        break;
                    }
                    case 9:
                    {
                        m.SuperEnergy = r.ReadInt32();
                        break;
                    }
                    default:
                    {
                        r.SkipField(wireType);
                        break;
                    }
                }
            }
        }

        // 便捷入口：一次性序列化 / 反序列化。
        public static byte[] ToByteArray(PMAuthoritativePlayerState m)
        {
            PMNetWriter w = new PMNetWriter();
            Write(w, m);
            return w.ToArray();
        }

        public static PMAuthoritativePlayerState ParseFrom(byte[] data)
        {
            return ParseFrom(data, 0, data.Length);
        }

        public static PMAuthoritativePlayerState ParseFrom(byte[] data, int offset, int count)
        {
            PMAuthoritativePlayerState m = new PMAuthoritativePlayerState();
            MergeFrom(new PMNetReader(data, offset, count), m);
            return m;
        }

    }

